import{_ as t,o as a,c as o,a0 as i}from"./chunks/framework.BLL-IG04.js";const p=JSON.parse('{"title":"Explanation: claims, tiers, and the evidence bar","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/claims.md","filePath":"explanation/claims.md"}'),d={name:"explanation/claims.md"};function c(s,e,n,r,l,m){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="explanation-claims-tiers-and-the-evidence-bar" tabindex="-1">Explanation: claims, tiers, and the evidence bar <a class="header-anchor" href="#explanation-claims-tiers-and-the-evidence-bar" aria-label="Permalink to &quot;Explanation: claims, tiers, and the evidence bar&quot;">​</a></h1><p>mimus is built on one observation: documentation is full of <em>claims</em> — statements that are either still true or quietly false. A critic&#39;s job is to enumerate them and prove each one, or stay silent.</p><h2 id="claim-taxonomy" tabindex="-1">Claim taxonomy <a class="header-anchor" href="#claim-taxonomy" aria-label="Permalink to &quot;Claim taxonomy&quot;">​</a></h2><p>Extraction classifies backticked spans, code blocks and prose patterns into:</p><table tabindex="0"><thead><tr><th>kind</th><th>example claim</th><th>verified by</th></tr></thead><tbody><tr><td><code>path</code></td><td><code>`src/lib.rs`</code></td><td>filesystem</td></tr><tr><td><code>command</code></td><td><code>`cargo test -p foo`</code></td><td>binary on PATH (no exec)</td></tr><tr><td><code>symbol</code></td><td><code>`IndexStore`</code></td><td>kuda index (symbol checker)</td></tr><tr><td><code>count</code></td><td>&quot;357 suites / 4,298 tests&quot;</td><td>recomputation</td></tr><tr><td><code>link</code></td><td><code>[docs](https://…)</code></td><td>link checker</td></tr><tr><td><code>behavior</code></td><td>prose asserting code does X</td><td>rules + semantic tier</td></tr></tbody></table><p>Command claims are conservative by design: only spans whose first token is a known binary (<code>cargo</code>, <code>git</code>, <code>npm</code>, <code>dagger</code>, <code>kuda</code>, <code>mimus</code>, …) classify as commands — otherwise <code>pub fn</code> and <code>data Eq</code> get read as shell.</p><h2 id="verification-tiers" tabindex="-1">Verification tiers <a class="header-anchor" href="#verification-tiers" aria-label="Permalink to &quot;Verification tiers&quot;">​</a></h2><ul><li><strong>Mechanical</strong> — deterministic and offline: paths, commands, rules. This is the <code>mimus check</code> gate; if it flags something, the evidence is reproducible by anyone.</li><li><strong>Semantic</strong> — advisory: prose-vs-behavior (&quot;retries 3 times&quot; vs the code&#39;s 5), comment-vs-adjacent-code, ADR-vs-reality. Reports with evidence; a human adjudicates. <strong>Can never gate</strong> — that is load-bearing, not a limitation.</li></ul><p>Style opinions are never emitted at all.</p><h2 id="the-evidence-bar" tabindex="-1">The evidence bar <a class="header-anchor" href="#the-evidence-bar" aria-label="Permalink to &quot;The evidence bar&quot;">​</a></h2><p>Every violation is <code>claim + evidence + fix(optional)</code>. If a checker cannot cite its proof, it emits nothing — false positives kill a critic faster than false negatives ever could. This is why <code>command</code> has an allowlist, why a bad rule regex is silence + a doctor complaint, and why the semantic tier exists separately from the gate.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p><code>[sources]</code> in <code>mimus.toml</code>: <code>docs</code> (glob list), <code>comments</code> (code comments — TODOs, claims in <code>///</code>), and <code>cards</code> — the kuda artifacts get audited as claims too, closing the loop: kuda remembers, mimus doubts, even about the memory itself.</p>',13)])])}const u=t(d,[["render",c]]);export{p as __pageData,u as default};
